def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            # Mark the middle/background color when it is bracketed by the
            # repeated foreground color, as in the demonstration.
            if row[c - 1] == 0 and row[c] == 1 and row[c + 1] == 0:
                out[r][c] = 2
    return out

